UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-22', "description" = CASE WHEN "description" LIKE '%American/NMJL not stated%' THEN trim(replace("description", 'American/NMJL not stated on the club''s page.', '') || ' Its own page says: "Begin your American Mahjong journey with a Mahjong 101 Bootcamp session, where you will learn the basics of the game and receive your National Mah Jongg League card. Throughout the retreat you will mo"') ELSE "description" END, "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'lenox-american-mahjong-retreat-at-canyon-ranch-lenox' AND "status" = 'NEEDS_REVIEW'; -- American Mahjong Retreat at Canyon Ranch Lenox (Lenox, MA): "Begin your American Mahjong journey with a Mahjong 101 Bootcamp session, where you will learn the basics of the game and receive your National Mah Jongg League card. Throughout the retreat you will mo" https://www.canyonranch.com/lenox/retreats/american-mahjong-retreat-oct-2026
